<?php
declare(strict_types=1);
require_once __DIR__.'/includes/init.php';require_once __DIR__.'/csrf_helper.php';require_once __DIR__.'/includes/staff_workspaces.php';require_once __DIR__.'/includes/shop_returns.php';
if(!isset($_SESSION['trener_id'])){header('Location: login.php');exit;}
$position=staffActivePosition();if(!in_array($position,['order_operator','catalog_manager','finance_manager'],true)){http_response_code(403);exit('Přístup je určen obsluze objednávek, skladu a hospodáři.');}
$actor=(int)$_SESSION['trener_id'];$error='';$success='';$available=true;try{$pdo->query('SELECT id FROM shop_return_cases LIMIT 0');}catch(PDOException){$available=false;}
function srH(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function srAmount(string $v):int{if(!preg_match('/^[0-9]{1,9}(?:[.,][0-9]{1,2})?$/D',trim($v)))throw new DomainException('Zadejte nezápornou částku s nejvýše dvěma desetinnými místy.');$p=explode('.',str_replace(',','.',trim($v)));return(int)$p[0]*100+(int)str_pad($p[1]??'',2,'0');}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if(!csrf_verify((string)($_POST['csrf_token']??''))){http_response_code(403);$error='Formulář vypršel. Obnovte stránku.';}
 else try{
  if(!$available)throw new DomainException('Skladová migrace není připravena.');$reason=(string)($_POST['reason']??'');$confirmed=($_POST['confirmed']??'')==='1';$key=(string)($_POST['request_key']??'');$id=(int)($_POST['case_id']??0);$revision=(int)($_POST['revision']??0);$on=(string)($_POST['occurred_on']??'');
  $action=(string)($_POST['action']??'');$actionRoles=['open'=>['order_operator','catalog_manager'],'receive'=>['order_operator'],'dispose'=>['catalog_manager'],'physical'=>['order_operator'],'assign'=>['order_operator','catalog_manager'],'finance'=>['finance_manager'],'attach_correction'=>['finance_manager'],'exchange_reserve'=>['order_operator'],'exchange_issue'=>['order_operator'],'cancel'=>['order_operator','catalog_manager'],'close'=>['order_operator','catalog_manager'],'cancel_after_finance'=>['finance_manager']];if(!in_array($position,$actionRoles[$action]??[],true)){http_response_code(403);exit('Přepněte do oprávněné pracovní pozice pro tento úkon.');}
  switch($action){
   case 'open':$result=shopReturnOpen($pdo,['issue_movement_id'=>(int)($_POST['issue_movement_id']??0),'quantity'=>(int)($_POST['quantity']??0),'request_type'=>(string)($_POST['request_type']??''),'owner_trainer_id'=>(int)($_POST['owner_trainer_id']??0),'next_due_on'=>(string)($_POST['next_due_on']??''),'occurred_on'=>$on,'contact_path'=>(string)($_POST['contact_path']??''),'customer_request'=>(string)($_POST['customer_request']??''),'policy_evidence'=>(string)($_POST['policy_evidence']??''),'request_key'=>$key],$actor,$reason,$confirmed);break;
   case 'receive':$result=shopReturnReceive($pdo,$id,$revision,(string)($_POST['ownership']??''),$on,$actor,$reason,$confirmed,$key);break;
   case 'dispose':$result=shopReturnDispose($pdo,$id,$revision,(string)($_POST['disposition']??''),$on,$actor,$reason,$confirmed,$key);break;
   case 'physical':$result=shopReturnPhysicalResolution($pdo,$id,$revision,(string)($_POST['resolution']??''),$on,$actor,$reason,$confirmed,$key);break;
   case 'assign':$result=shopReturnAssign($pdo,$id,$revision,(int)($_POST['owner_trainer_id']??0),(string)($_POST['next_due_on']??''),(string)($_POST['contact_path']??''),$actor,$reason,$confirmed,$key);break;
   case 'attach_correction':$result=shopReturnAttachCorrection($pdo,$id,$revision,(int)($_POST['correction_document_id']??0),(int)($_POST['refund_decision_id']??0),srAmount((string)($_POST['correction_amount']??'')),$actor,$reason,$confirmed,$key);break;
   case 'finance':$result=shopReturnFinancialResolution($pdo,$id,$revision,(string)($_POST['resolution']??''),(int)($_POST['correction_document_id']??0),(int)($_POST['refund_decision_id']??0),(string)($_POST['evidence']??''),$actor,$reason,$confirmed,$key);break;
   case 'exchange_reserve':$result=shopReturnExchangeReserve($pdo,$id,$revision,(int)($_POST['variant_id']??0),srAmount((string)($_POST['replacement_amount']??'')),$actor,$reason,$confirmed,$key);break;
   case 'exchange_issue':$result=shopReturnExchangeIssue($pdo,$id,$revision,(string)($_POST['recipient']??''),$on,$actor,$reason,$confirmed,$key);break;
   case 'cancel_after_finance':$result=shopReturnCancelAfterFinance($pdo,$id,$revision,$actor,$reason,$confirmed,$key);break;
   case 'cancel':$result=shopReturnCancel($pdo,$id,$revision,$actor,$reason,$confirmed,$key);break;
   case 'close':$result=shopReturnClose($pdo,$id,$revision,$actor,$reason,$confirmed,$key);break;
   default:throw new DomainException('Neznámý úkon.');
  }$success='Úkon zaznamenán v případu #'.$result['id'].'.';
 }catch(DomainException|ShopInventoryException|InvalidArgumentException $e){http_response_code(422);$error=$e->getMessage();}
}
$cases=$available?$pdo->query('SELECT c.*,t.jmeno AS owner_name FROM shop_return_cases c LEFT JOIN treneri t ON t.id=c.owner_trainer_id ORDER BY CASE WHEN c.state=\'open\' THEN 0 ELSE 1 END,c.next_due_on,c.id DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC):[];
$owners=$available?$pdo->query("SELECT DISTINCT t.id,t.jmeno FROM treneri t WHERE t.aktivni=1 AND (EXISTS(SELECT 1 FROM staff_user_positions p WHERE p.trainer_id=t.id AND p.position_code IN ('order_operator','catalog_manager')) OR EXISTS(SELECT 1 FROM staff_superadmins s WHERE s.trainer_id=t.id)) ORDER BY t.jmeno")->fetchAll(PDO::FETCH_ASSOC):[];
$issueWarnings=[];$issues=[];if($available){foreach($pdo->query("SELECT id FROM shop_stock_movements WHERE kind='issue' ORDER BY id DESC LIMIT 200")->fetchAll(PDO::FETCH_COLUMN)as$movementId){try{$i=shopReturnIssueSource($pdo,(int)$movementId);}catch(DomainException $e){$issueWarnings[]='Výdej #'.(int)$movementId.': '.$e->getMessage();continue;}if(!$i)continue;$q=$pdo->prepare('SELECT public_code FROM shop_orders WHERE id=?');$q->execute([$i['order_id']]);$i['public_code']=$q->fetchColumn();$issues[]=$i;}}
$variants=$available?$pdo->query("SELECT v.id,v.sku,p.name,b.physical_quantity-b.reserved_quantity-b.blocked_quantity AS available_quantity FROM shop_stock_balances b JOIN shop_variants v ON v.id=b.variant_id JOIN shop_products p ON p.id=v.product_id WHERE b.mode='tracked' ORDER BY p.name,v.sku")->fetchAll(PDO::FETCH_ASSOC):[];
$labels=['withdrawal'=>'Odstoupení','voluntary_exchange'=>'Dobrovolná výměna','claim'=>'Reklamace','open'=>'Otevřeno','closed'=>'Uzavřeno','cancelled'=>'Zrušeno','requested'=>'Čeká na převzetí','owned_blocked'=>'Vlastní kusy převzaty do blokace','custody'=>'Cizí kusy v péči','custody_returned'=>'Cizí kusy vráceny zákazníkovi','return_waived'=>'Vrácení není požadováno','pending'=>'Čeká na vyřešení','saleable'=>'Uvolněno do prodeje','written_off'=>'Odepsáno','not_owned'=>'Cizí vlastnictví','not_received'=>'Nepřevzato','no_adjustment'=>'Bez cenové opravy','adjustment'=>'Účetní řešení potvrzeno'];
$eventLabels=['opened'=>'Požadavek založen','received'=>'Kusy převzaty','disposition'=>'Prodejnost posouzena','physical_resolution'=>'Fyzické řešení doloženo','assigned'=>'Další krok předán','correction_linked'=>'Opravný doklad připojen','financial_resolution'=>'Finanční řešení potvrzeno','exchange_reserved'=>'Nová varianta rezervována','exchange_issued'=>'Nová varianta vydána','cancelled'=>'Požadavek zrušen','cancelled_after_finance'=>'Výměna zrušena po úplném finančním vypořádání','closed'=>'Případ uzavřen'];
function srFields(string $action,?array $case=null):void{echo csrf_field().'<input type="hidden" name="action" value="'.srH($action).'"><input type="hidden" name="request_key" value="'.bin2hex(random_bytes(16)).'">';if($case)echo '<input type="hidden" name="case_id" value="'.(int)$case['id'].'"><input type="hidden" name="revision" value="'.(int)$case['revision'].'">';}
function srConfirm(string $button):void{echo '<label class="form-label d-block mt-2">Interní důvod úkonu<input class="form-control" name="reason" minlength="10" maxlength="1000" required></label><label class="d-block my-2"><input type="checkbox" name="confirmed" value="1" required> Potvrzuji podklady a provedený úkon</label><button class="btn btn-primary">'.srH($button).'</button>';}
function srDate():void{echo '<label class="form-label">Skutečné datum<input class="form-control" type="date" name="occurred_on" max="'.date('Y-m-d').'" value="'.date('Y-m-d').'" required></label>';}
function srOwner(array $owners,int $selected=0):void{echo '<label class="form-label">Odpovědný pracovník<select class="form-select" name="owner_trainer_id" required>';foreach($owners as $o)echo '<option value="'.(int)$o['id'].'"'.((int)$o['id']===$selected?' selected':'').'>'.srH($o['jmeno']).'</option>';echo '</select></label>';}
?>
<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Vratky, výměny a reklamace</title><?php require_once __DIR__.'/includes/ui_shell.php';appUiAssets();?></head><body><?php require __DIR__.'/hlavicka.php';?><main class="container py-4"><h1>Vratky, výměny a reklamace</h1><p>Požadavek zákazníka, fyzické převzetí, posouzení kusů a peněžní řešení se potvrzují samostatně. Převzetí reklamace neznamená její uznání. Lhůtu zadá obsluha podle schválené metodiky.</p>
<p><a href="eshop_orders_admin.php">Objednávky a výdej</a><?php if($position==='finance_manager'):?> · <a href="accounting_adjustments_admin.php">Opravné doklady a peněžní vratky</a> · <a href="accounting_ledger_admin.php">Úhrada doplatku</a><?php endif;?></p>
<?php if($error):?><div class="alert alert-danger" role="alert"><?=srH($error)?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?=srH($success)?></div><?php endif;?>
<?php if(!$available):?><div class="alert alert-warning">Skladová migrace ještě není připravena.</div><?php else:?>
<?php if($position!=='finance_manager'):?><details class="card card-body mb-4"><summary>Založit požadavek k vydanému zboží</summary><form method="post" class="mt-3"><?php srFields('open');?><label class="form-label d-block">Původní fyzický výdej<select class="form-select" name="issue_movement_id" required><option value="">Vyberte doložený výdej</option><?php foreach($issues as $i):?><option value="<?=(int)$i['id']?>"><?=srH('#'.$i['id'].' · '.$i['public_code'].' · '.$i['product_name_snapshot'].' / '.$i['sku_snapshot'].' · '.abs((int)$i['physical_delta']).' ks · '.$i['effective_on'])?></option><?php endforeach;?></select></label><div class="row g-3"><label class="col-md-4">Druh požadavku<select class="form-select" name="request_type"><option value="withdrawal">Odstoupení</option><option value="voluntary_exchange">Dobrovolná výměna</option><option value="claim">Reklamace</option></select></label><label class="col-md-2">Počet kusů<input class="form-control" type="number" name="quantity" min="1" value="1" required></label><div class="col-md-3"><?php srDate();?></div><div class="col-md-3"><?php srOwner($owners,$actor);?></div><label class="col-md-4">Další termín podle metodiky<input class="form-control" type="date" name="next_due_on" required></label><label class="col-md-8">Kontaktní cesta<input class="form-control" name="contact_path" maxlength="300" required></label><label class="col-md-6">Požadované řešení zákazníka<textarea class="form-control" name="customer_request" required></textarea><small>Důvod odstoupení zákazník uvádět nemusí.</small></label><label class="col-md-6">Použitá metodika / dohoda<textarea class="form-control" name="policy_evidence" required></textarea></label></div><?php srConfirm('Založit případ'); ?></form></details><?php endif;?>
<?php foreach($issueWarnings as$warning):?><div class="alert alert-warning"><?=srH($warning)?></div><?php endforeach;?><h2 class="h4">Případy a další kroky</h2><?php foreach($cases as $c):$snapshot=json_decode($c['original_snapshot_json'],true);?><article class="card card-body mb-3" id="case-<?=(int)$c['id']?>"><h3 class="h5">#<?=(int)$c['id']?> <?=srH($labels[$c['request_type']])?> · <?=srH($snapshot['label'].' / '.$snapshot['sku'])?> · <?=(int)$c['quantity']?> ks</h3><p><strong><?=srH($labels[$c['state']])?></strong> · <?=srH($labels[$c['physical_state']])?> · <?=srH($labels[$c['disposition']])?><br>Odpovídá <?=srH($c['owner_name'])?> · další termín <strong><?=srH($c['next_due_on'])?></strong> · <?=srH($c['contact_path'])?><br><?=srH($c['customer_request'])?><br>Metodika: <?=srH($c['policy_evidence'])?><br>Původní hodnota <?=srH(number_format((int)$c['original_amount_minor']/100,2,',',' '))?> Kč · účetní stav: <?=srH($labels[$c['finance_state']])?></p>
<?php if($c['exchange_variant_id']):?><p>Nová varianta #<?=(int)$c['exchange_variant_id']?> · dohodnutá cena <?=srH(number_format((int)$c['exchange_amount_minor']/100,2,',',' '))?> Kč · <strong>rozdíl <?=srH(number_format((int)$c['exchange_delta_minor']/100,2,',',' '))?> Kč</strong> · <?=$c['exchange_issue_movement_id']?'Výdej doložen':'Rezervováno, čeká na výdej'?></p><?php endif;?>
<?php if($c['correction_document_id']):?><p>Opravný doklad #<?=(int)$c['correction_document_id']?> · vratka #<?=(int)$c['refund_decision_id']?> · <?=srH($c['finance_evidence'])?></p><?php endif;?>
<?php if($c['state']==='open'):?>
<?php if($position==='order_operator'&&$c['physical_state']==='requested'):?><details><summary>Převzít kusy</summary><form method="post"><?php srFields('receive',$c);srDate();?><label class="form-label">Vlastnictví<select class="form-select" name="ownership"><option value="owned">Převzato zpět do vlastnictví oddílu – blokované zásoby</option><?php if($c['request_type']==='claim'):?><option value="custody">Cizí kus pouze do péče na reklamaci</option><?php endif;?></select></label><?php srConfirm('Potvrdit skutečné převzetí'); ?></form></details><?php endif;?>
<?php if($position==='catalog_manager'&&$c['physical_state']==='owned_blocked'&&$c['disposition']==='pending'):?><details><summary>Posoudit vlastní blokované kusy</summary><form method="post"><?php srFields('dispose',$c);srDate();?><select class="form-select" name="disposition"><option value="unblock">Schválit prodejnost a uvolnit</option><option value="writeoff">Poškozené kusy odepsat</option></select><?php srConfirm('Potvrdit posouzení'); ?></form></details><?php endif;?>
<?php if($position==='order_operator'&&in_array($c['physical_state'],['requested','custody'],true)):?><details><summary>Jiné fyzické řešení</summary><form method="post"><?php srFields('physical',$c);srDate();?><select class="form-select" name="resolution"><?php if($c['physical_state']==='custody'):?><option value="custody_returned">Cizí kus vrácen zákazníkovi</option><option value="ownership_accepted">Věc převzata zpět do vlastnictví oddílu</option><?php else:?><option value="return_waived">Vrácení kusu se podle dohody nevyžaduje</option><?php endif;?></select><?php srConfirm('Potvrdit fyzické řešení'); ?></form></details><?php endif;?>
<?php if($position==='order_operator'&&$c['request_type']==='voluntary_exchange'&&!$c['exchange_reservation_id']):?><details><summary>Rezervovat novou velikost</summary><form method="post"><?php srFields('exchange_reserve',$c);?><label class="form-label">Nová varianta<select class="form-select" name="variant_id"><?php foreach($variants as $v):if((int)$v['id']===(int)$c['variant_id'])continue;?><option value="<?=(int)$v['id']?>"><?=srH($v['name'].' / '.$v['sku'].' · dostupné '.$v['available_quantity'].' ks')?></option><?php endforeach;?></select></label><label class="form-label">Dohodnutá celková cena nových kusů (Kč)<input class="form-control" name="replacement_amount" inputmode="decimal" required></label><?php srConfirm('Rezervovat novou variantu'); ?></form></details><?php endif;?>
<?php if($position==='order_operator'&&$c['exchange_reservation_id']&&!$c['exchange_issue_movement_id']):?><details><summary>Vydat novou variantu</summary><form method="post"><?php srFields('exchange_issue',$c);srDate();?><label class="form-label">Kdo převzal nové kusy<input class="form-control" name="recipient" maxlength="200" required></label><?php srConfirm('Potvrdit skutečný výdej výměny'); ?></form></details><?php endif;?>
<?php if($position==='finance_manager'&&$c['finance_state']==='pending'):?><details><summary>Připojit část opravného dokladu</summary><p>U vrácení již vyměněného kusu lze připojit samostatnou opravu původního prodeje a opravu dřívějšího doplatku. Součet musí přesně pokrýt vracenou hodnotu.</p><form method="post"><?php srFields('attach_correction',$c);?><label class="form-label">ID vydaného opravného dokladu<input class="form-control" type="number" min="1" name="correction_document_id" required></label><label class="form-label">Část opravy pro tento případ (Kč)<input class="form-control" name="correction_amount" inputmode="decimal" required></label><label class="form-label">ID rozhodnutí o vratce<input class="form-control" type="number" min="1" name="refund_decision_id"></label><?php srConfirm('Připojit účetní podklad'); ?></form></details><details><summary>Potvrdit finanční a dokladové řešení</summary><p>Opravu a případnou vratku nejprve zpracujte v účetní evidenci. Doplatek výměny má zdroj „shop_return“, ID tohoto případu. Tímto formulářem se peníze nepřijímají ani neodesílají.</p><form method="post"><?php srFields('finance',$c);?><select class="form-select" name="resolution"><option value="no_adjustment">Bez změny ceny a bez peněžního závazku</option><option value="adjustment">Oprava / rozdíl ceny vyřešen účetním podkladem</option></select><div class="row g-3"><label class="col-md-4">ID vydaného opravného dokladu<input class="form-control" type="number" min="1" name="correction_document_id"></label><label class="col-md-4">ID rozhodnutí o peněžní vratce<input class="form-control" type="number" min="1" name="refund_decision_id"></label><label class="col-md-12">Podklad finančního řešení<textarea class="form-control" name="evidence" minlength="10" required></textarea></label></div><?php srConfirm('Potvrdit účetní vazby'); ?></form></details><?php endif;?>
<?php if($position==='finance_manager'&&$c['request_type']==='voluntary_exchange'&&$c['physical_state']==='requested'&&(int)$c['exchange_delta_minor']>0):?><details><summary>Zrušit výměnu po opravě fakturovaného doplatku</summary><p>Původní kus musí zůstat zákazníkovi. Nejprve dokončete opravný doklad doplatku, uvolnění přídělů a skutečné vrácení všech přijatých peněz. Zrušení uvolní pouze rezervovanou novou velikost.</p><form method="post"><?php srFields('cancel_after_finance',$c);srConfirm('Zrušit finančně vypořádanou výměnu'); ?></form></details><?php endif;?>
<?php if($position!=='finance_manager'):?><details><summary>Předat další krok</summary><form method="post"><?php srFields('assign',$c);srOwner($owners,(int)$c['owner_trainer_id']);?><label class="form-label">Další termín<input class="form-control" type="date" name="next_due_on" value="<?=srH($c['next_due_on'])?>" required></label><label class="form-label">Kontakt<input class="form-control" name="contact_path" value="<?=srH($c['contact_path'])?>" required></label><?php srConfirm('Uložit odpovědnost a další krok'); ?></form></details><details><summary>Uzavřít vyřešený případ / zrušit dosud neprovedený požadavek</summary><form method="post"><?php srFields('close',$c);srConfirm('Uzavřít po kontrole všech kroků'); ?></form><?php if($c['physical_state']==='requested'&&$c['finance_state']==='pending'):?><form method="post" class="mt-3"><?php srFields('cancel',$c);srConfirm('Zrušit neprovedený požadavek'); ?></form><?php endif;?></details><?php endif;?>
<?php endif;?>
<details class="mt-2"><summary>Účetní podklady</summary><ul><?php $q=$pdo->prepare('SELECT * FROM shop_return_finance_links WHERE case_id=? ORDER BY id');$q->execute([$c['id']]);foreach($q->fetchAll(PDO::FETCH_ASSOC)as$link):?><li>Oprava #<?=(int)$link['correction_document_id']?> · <?=srH(number_format((int)$link['amount_minor']/100,2,',',' '))?> Kč · rozhodnutí o vratce #<?=(int)$link['refund_decision_id']?></li><?php endforeach;?></ul></details><details class="mt-2"><summary>Historie případu</summary><ul><?php $q=$pdo->prepare('SELECT event_type,actor_id,reason,occurred_on,recorded_at FROM shop_return_events WHERE case_id=? ORDER BY id');$q->execute([$c['id']]);foreach($q->fetchAll(PDO::FETCH_ASSOC)as$e):?><li><?=srH($e['occurred_on'].' · '.($eventLabels[$e['event_type']]??$e['event_type']).' · pracovník #'.$e['actor_id'].' · '.$e['reason'].' (zapsáno '.$e['recorded_at'].')')?></li><?php endforeach;?></ul></details></article><?php endforeach;?><?php endif;?></main></body></html>
